        let ItemKind::Weapon {
            preferred_attack,
            reach_m,
            precision,
            melee,
            ranged,
            skills,
            moment_of_inertia_kg_m2,
            ..
        } = &definition.kind
        else {
            return Err(AuthoredMeleeWeaponError::NotWeapon {
                weapon: weapon_id.to_owned(),
            });
        };
        if !melee || *ranged {
            return Err(AuthoredMeleeWeaponError::NotMeleeOnly {
                weapon: weapon_id.to_owned(),
            });
        }
        let moment_of_inertia_kg_m2 = *moment_of_inertia_kg_m2;
